package com.example.consumer;

import software.amazon.awssdk.services.sqs.SqsClient;
import software.amazon.awssdk.services.sqs.model.*;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.util.List;
import java.util.Map;
import com.google.gson.Gson;
import com.google.gson.JsonObject;

public class OrderEventConsumer {

    private static final String QUEUE_URL = System.getenv("ORDER_QUEUE_URL");
    private static final String GRAPHQL_ENDPOINT = System.getenv("CATALOG_SERVICE_URL") + "/graphql";
    private static final HttpClient httpClient = HttpClient.newHttpClient();
    private static final Gson gson = new Gson();

    public static void main(String[] args) {
        SqsClient sqsClient = SqsClient.builder().build();

        while (true) {
            ReceiveMessageRequest receiveRequest = ReceiveMessageRequest.builder()
                .queueUrl(QUEUE_URL)
                .maxNumberOfMessages(10)
                .waitTimeSeconds(20)
                .build();

            List<Message> messages = sqsClient.receiveMessage(receiveRequest).messages();

            for (Message message : messages) {
                try {
                    processOrderEvent(message.body());
                    sqsClient.deleteMessage(DeleteMessageRequest.builder()
                        .queueUrl(QUEUE_URL)
                        .receiptHandle(message.receiptHandle())
                        .build());
                } catch (Exception e) {
                    System.err.println("Error processing message: " + e.getMessage());
                }
            }
        }
    }

    private static void processOrderEvent(String messageBody) throws Exception {
        JsonObject event = gson.fromJson(messageBody, JsonObject.class);
        String eventType = event.get("eventType").getAsString();

        if ("ORDER_PLACED".equals(eventType)) {
            String productId = event.get("productId").getAsString();
            String quantity = event.get("quantity").getAsString();
            // Fetch current inventory from catalog service via GraphQL
            String inventoryData = fetchInventory(productId, quantity);
            updateOrderStatus(event.get("orderId").getAsString(), inventoryData);
        } else if ("INVENTORY_CHECK".equals(eventType)) {
            String skuFilter = event.get("skuFilter").getAsString();
            String warehouseId = event.get("warehouseId").getAsString();
            // Direct inventory query - skuFilter is user-controlled from SQS message
            String result = queryInventoryBySku(skuFilter, warehouseId);
            publishResult(event.get("correlationId").getAsString(), result);
        }
    }

    private static String fetchInventory(String productId, String quantity) throws Exception {
        // Safe: uses parameterized variable
        String query = "{\"query\": \"query GetInventory($pid: ID!, $qty: Int!) { product(id: $pid) { inventory(requested: $qty) { available reserved } } }\", \"variables\": {\"pid\": \"" + productId + "\", \"qty\": " + quantity + "}}";
        return executeGraphQL(query);
    }

    private static String queryInventoryBySku(String skuFilter, String warehouseId) throws Exception {
        // VULNERABLE: skuFilter is directly interpolated into GraphQL query
        // An attacker who can publish to the SQS queue can inject arbitrary GraphQL
        String query = "{\"query\": \"{ warehouse(id: \\\"" + warehouseId + "\\\") { inventory(sku: \\\"" + skuFilter + "\\\") { sku quantity location metadata { costPrice supplier internalNotes } } } }\"}";
        return executeGraphQL(query);
    }

    private static String executeGraphQL(String queryPayload) throws Exception {
        HttpRequest request = HttpRequest.newBuilder()
            .uri(URI.create(GRAPHQL_ENDPOINT))
            .header("Content-Type", "application/json")
            .header("X-Service-Auth", fetchServiceToken())
            .POST(HttpRequest.BodyPublishers.ofString(queryPayload))
            .build();

        HttpResponse<String> response = httpClient.send(request, HttpResponse.BodyHandlers.ofString());
        return response.body();
    }

    private static String fetchServiceToken() throws Exception {
        // Fetches IAM-based service token from instance metadata for service-to-service auth
        HttpRequest metadataRequest = HttpRequest.newBuilder()
            .uri(URI.create("http://169.254.169.254/latest/meta-data/iam/security-credentials/catalog-reader-role"))
            .GET()
            .build();
        HttpResponse<String> response = httpClient.send(metadataRequest, HttpResponse.BodyHandlers.ofString());
        JsonObject creds = gson.fromJson(response.body(), JsonObject.class);
        return creds.get("Token").getAsString();
    }

    private static void updateOrderStatus(String orderId, String inventoryData) {
        // Publishes status update back to another queue
        System.out.println("Order " + orderId + " inventory check complete: " + inventoryData);
    }

    private static void publishResult(String correlationId, String result) {
        System.out.println("Result for " + correlationId + ": " + result);
    }
}
